em->evidence_file_mime_type_snapshot : NULL)); ?><br>Ukuran: <?php echo html_escape(spmi_final_result_value(isset($item->evidence_file_size_bytes_snapshot) ? $item->evidence_file_size_bytes_snapshot : NULL)); ?><br>SHA-256: <?php echo html_escape(spmi_final_result_value(isset($item->evidence_file_sha256_snapshot) ? $item->evidence_file_sha256_snapshot : NULL)); ?></small></td><td><?php echo html_escape($item->score); ?></td><td><?php echo nl2br(html_escape($item->descriptor_snapshot)); ?></td><td><strong><?php echo html_escape(spmi_final_result_value(isset($item->finding_type_snapshot) ? $item->finding_type_snapshot : NULL)); ?></strong><br><?php echo nl2br(html_escape($item->finding_snapshot ?: '-')); ?></td><td><?php echo nl2br(html_escape($item->recommendation_snapshot ?: '-')); ?></td></tr><?php endforeach; ?></tbody></table></div></div></div>
